require_once __DIR__.'/config/config.php';require_once __DIR__.'/includes/functions.php';require_login();
$id=(int)($_GET['order_id']??0);
if(current_user_id()){$s=$pdo->prepare('SELECT o.*,r.receipt_number,r.issued_date,p.payment_method,p.payment_status,u.full_name,u.email FROM orders o JOIN receipts r ON r.order_id=o.order_id JOIN users u ON u.user_id=o.user_id LEFT JOIN payments p ON p.order_id=o.order_id WHERE o.order_id=? AND o.user_id=?');$s->execute([$id,current_user_id()]);}
else if(is_admin()){$s=$pdo->prepare('SELECT o.*,r.receipt_number,r.issued_date,p.payment_method,p.payment_status,u.full_name,u.email FROM orders o JOIN receipts r ON r.order_id=o.order_id JOIN users u ON u.user_id=o.user_id LEFT JOIN payments p ON p.order_id=o.order_id WHERE o.order_id=?');$s->execute([$id]);}
else redirect('/login.php');
$o=$s->fetch();if(!$o){$errorCode=404;require __DIR__.'/error.php';exit;}$s=$pdo->prepare('SELECT oi.*,p.image,p.image_alt,p.category_id,c.category_name FROM order_items oi LEFT JOIN products p ON p.product_id=oi.product_id LEFT JOIN categories c ON c.category_id=p.category_id WHERE oi.order_id=?');$s->execute([$id]);$items=$s->fetchAll();
$pageTitle='Digital Receipt';require __DIR__.'/includes/header.php';
?>
<div class="receipt card"><div class="receipt-head"><div><h1>BuildSmart</h1><p class="muted">Digital Transaction Receipt</p></div><div class="text-right"><strong><?= e($o['receipt_number']) ?></strong><br><span class="small muted"><?= e($o['issued_date']) ?></span></div></div><p><strong>Customer:</strong> <?= e($o['full_name']) ?><br><strong>Email:</strong> <?= e($o['email']) ?><br><strong>Order:</strong> #<?= $id ?><br><strong>Payment:</strong> <?= e($o['payment_method']) ?> (<?= e($o['payment_status']) ?>)</p><p><strong>Deliver to:</strong></p><div class="small"><?= delivery_block_html($o, (string)$o['full_name'], '', false) ?></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><div class="cart-prod"><div class="thumb"><?= product_visual($i) ?></div><span><?= e($i['product_name']) ?></span></div></td><td><?= $i['quantity'] ?></td><td><?= money($i['unit_price']) ?></td><td><?= money($i['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="text-right">Items subtotal: <?=money(array_sum(array_column($items,'subtotal'))) ?><br>Delivery fee: <?=money($o['delivery_fee']??0)?></p><h2 class="text-right u-mt-18">Total: <?= money($o['total_amount']) ?></h2><div class="receipt-actions"><button type="button" class="btn btn-primary" onclick="window.print()">Download PDF</button> <button type="button" class="btn btn-outline" onclick="window.print()">Print Receipt</button><p class="small muted">In the print dialog, choose “Save as PDF” to download a PDF copy.</p></div></div>
